import assert from 'node:assert/strict';
import {test} from 'node:test';
import {handle} from '../src/app.ts';
import {createContext, forkContext} from '../src/context-factory.ts';
import {describeJob} from '../src/jobs.ts';
import {auditLabel} from '../src/job-types.ts';
import {traceSummary} from '../src/plugins/index.ts';
import {record0, audit0} from '../src/catalog/record0.ts';

test('end-to-end propagation through handle', () => {
  const job = { requestId: 'job-123', name: 'process-data' };
  const result = handle('trace-456', 'user-789', job);

  // Context construction
  assert.equal(result.context.traceId, 'trace-456');
  assert.equal(result.context.userId, 'user-789');
  assert.equal('requestId' in result.context, false);

  // Wire headers
  assert.equal(result.headers['x-request-id'], 'trace-456');

  // Logs
  assert.equal(result.logs.requestId, 'trace-456');
  assert.equal(result.logs.userId, 'user-789');

  // Response body wire output
  assert.equal(result.body.requestId, 'trace-456');

  // Forked context propagation in worker payload
  assert.equal(result.body.payload.trace, 'trace-456/worker');
  assert.equal(result.body.payload.name, 'process-data');

  // Unrelated Job identifier preserved
  assert.equal(result.body.payload.requestId, 'job-123');
  assert.equal(result.body.payload.audit, 'job:job-123');
});

test('unrelated Job identifier and auditLabel', () => {
  const job = { requestId: 'unrelated-job-id', name: 'audit-task' };
  assert.equal(auditLabel(job.requestId), 'job:unrelated-job-id');

  const context = createContext('trace-abc', 'user-xyz');
  const jobDesc = describeJob(job, context);
  assert.equal(jobDesc.requestId, 'unrelated-job-id');
  assert.equal(jobDesc.trace, 'trace-abc');
  assert.equal(jobDesc.audit, 'job:unrelated-job-id');
  assert.equal(jobDesc.name, 'audit-task');
});

test('context non-mutation on fork', () => {
  const original = createContext('root-trace', 'user-1');
  const forked = forkContext(original, 'child');

  assert.equal(original.traceId, 'root-trace');
  assert.equal(forked.traceId, 'root-trace/child');
  assert.equal(forked.userId, 'user-1');
  assert.notEqual(original, forked);
  assert.equal('requestId' in original, false);
  assert.equal('requestId' in forked, false);
});

test('traceSummary and plugin propagation', () => {
  const context = createContext('plugin-trace', 'plugin-user');
  const summary = traceSummary(context);

  assert.equal(summary.length, 8);
  for (let i = 0; i < 8; i++) {
    assert.equal(summary[i].requestId, 'plugin-trace');
    assert.equal(summary[i].tag, `plugin${i}`);
    assert.equal(summary[i].user, 'plugin-user');
  }
});

test('unrelated catalog RequestContext and requestId preserved', () => {
  const catalogContext = { requestId: 'cat-req-1', category: 'books' };
  const rec = record0(catalogContext);
  assert.equal(rec.requestId, 'cat-req-1');
  assert.equal(rec.category, 'books');
  assert.equal(rec.label, 'record0:cat-req-1');
  assert.equal(audit0('cat-req-1'), 'audit0:cat-req-1');
});
